import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

matmul_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define TILE_SIZE_K 32
#define TILE_SIZE_N 64
#define TILE_SIZE_M 64

__global__ void matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int N, int K
) {
    // Block and grid indices
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global position in C matrix
    int row = by * TILE_SIZE_M + ty;
    int col = bx * TILE_SIZE_N + tx;

    // Shared memory for tiles
    __shared__ float As[TILE_SIZE_M][TILE_SIZE_K];
    __shared__ float Bs[TILE_SIZE_K][TILE_SIZE_N];

    // Accumulator
    float sum = 0.0f;

    // Loop over K dimension in tiles
    int num_tiles_k = (K + TILE_SIZE_K - 1) / TILE_SIZE_K;

    for (int t = 0; t < num_tiles_k; t++) {
        // Load tile of A
        int a_col = t * TILE_SIZE_K + tx;
        if (a_col < K && row < M) {
            As[ty][tx] = A[row * K + a_col];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile of B
        int b_row = t * TILE_SIZE_K + ty;
        if (b_row < K && col < N) {
            Bs[ty][tx] = B[b_row * N + col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum
        #pragma unroll
        for (int k = 0; k < TILE_SIZE_K; k++) {
            sum += As[ty][k] * Bs[k][tx];
        }

        __syncthreads();
    }

    // Write result to global memory
    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    // Get dimensions
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    // Create output tensor
    auto C = torch::zeros({M, N}, A.options());

    // Configure block and grid
    dim3 block(TILE_SIZE_N, TILE_SIZE_M);
    dim3 grid((N + TILE_SIZE_N - 1) / TILE_SIZE_N, 
              (M + TILE_SIZE_M - 1) / TILE_SIZE_M);

    // Launch kernel
    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, K
    );

    hipError_t err = hipGetLastError();
    if (err != hipSuccess) {
        printf("HIP Error: %s\\n", hipGetErrorString(err));
    }

    return C;
}
"""

matmul_hip = load_inline(
    name="matmul_hip",
    cpp_sources=matmul_cpp_source,
    functions=["matmul_hip"],
    verbose=True,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_hip = matmul_hip

    def forward(self, A, B):
        return self.matmul_hip.matmul_hip(A.cuda(), B.cuda())

